INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Planung und Anforderungsanalyse > Pflichtenhefte erstellen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Pflichtenheft zwingend alle technischen Details der Hardware enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus liegt auf Anforderungen, nicht Details"}, {"text": "Ja", "correct": false, "because": "Technische Details sind oft separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Pflichtenheft ohne Kundenabstimmung erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenvalidierung ist essenziell"}, {"text": "Ja", "correct": false, "because": "Ohne Abstimmung fehlt Verbindlichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Pflichtenheft erst dann gültig, wenn es rechtlich unterschrieben wurde?', 2, '[{"text": "Nein", "correct": true, "because": "Gültigkeit hängt von Zustimmung ab, nicht Unterschrift"}, {"text": "Ja", "correct": false, "because": "Formelle Unterschrift ist nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Dürfen Änderungen im Pflichtenheft nach Projektstart ausgeschlossen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibilität für Anpassungen ist nötig"}, {"text": "Ja", "correct": false, "because": "Statische Pflichtenhefte sind unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Erstellen eines Pflichtenhefts nur für große Projekte erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren von Klarheit"}, {"text": "Ja", "correct": false, "because": "Größe ist kein Kriterium"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt hat beim Erstellen eines Pflichtenhefts die höchste Priorität?', 3, '[{"text": "Klarheit der Anforderungen", "correct": true, "because": "Verhindert Missverständnisse"}, {"text": "Kostenabschätzung", "correct": false, "because": "Folge, nicht Priorität"}, {"text": "Zeitplanung", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist im Pflichtenheft zwingend enthalten?', 2, '[{"text": "Beschreibung der Soll-Zustände", "correct": true, "because": "Definiert Ziel des Projekts"}, {"text": "Liste der Lieferanten", "correct": false, "because": "Nicht zwingend"}, {"text": "Installationsanleitung", "correct": false, "because": "Späterer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist primär für die Erstellung des Pflichtenhefts verantwortlich?', 2, '[{"text": "Dienstleister", "correct": true, "because": "Formuliert Angebot an Kunden"}, {"text": "Kunde", "correct": false, "because": "Liefert Lastenheft"}, {"text": "Projektmanager", "correct": false, "because": "Koordiniert, nicht erstellt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann beim Erstellen eines Pflichtenhefts schwerwiegende Folgen haben?', 3, '[{"text": "Unklare Formulierungen", "correct": true, "because": "Führt zu Interpretationsfehlern"}, {"text": "Fehlende Unterschrift", "correct": false, "because": "Formell, aber nicht kritisch"}, {"text": "Zu kurzer Text", "correct": false, "because": "Länge ist sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt folgt direkt auf das Erstellen eines Pflichtenhefts?', 2, '[{"text": "Kundenfreigabe", "correct": true, "because": "Bestätigt Verbindlichkeit"}, {"text": "Hardwarebeschaffung", "correct": false, "because": "Späterer Schritt"}, {"text": "Systemtest", "correct": false, "because": "Endphase"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte müssen in einem Pflichtenheft typischerweise enthalten sein?', 4, '[{"text": "Funktionale Anforderungen", "correct": true, "because": "Beschreibt, was umgesetzt wird"}, {"text": "Nicht-funktionale Anforderungen", "correct": true, "because": "Definiert Rahmenbedingungen"}, {"text": "Abnahmekriterien", "correct": true, "because": "Bestimmt Erfolgskontrolle"}, {"text": "Marketingstrategie", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen das Erstellen eines Pflichtenhefts?', 3, '[{"text": "Kundeninterviews", "correct": true, "because": "Liefert direkte Anforderungen"}, {"text": "Workshops", "correct": true, "because": "Fördert Abstimmung"}, {"text": "Anforderungsanalyse", "correct": true, "because": "Strukturiert Informationen"}, {"text": "Regressionstests", "correct": false, "because": "Für Softwaretests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken können beim Erstellen eines Pflichtenhefts auftreten?', 3, '[{"text": "Missverständnisse mit Kunden", "correct": true, "because": "Fehlende Klarheit"}, {"text": "Unvollständige Anforderungen", "correct": true, "because": "Lücken in Planung"}, {"text": "Technische Überforderung", "correct": true, "because": "Zu komplexe Vorgaben"}, {"text": "Zu hohe Kosten", "correct": false, "because": "Kein Erstellungsrisiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen sind beim Erstellen eines Pflichtenhefts beteiligt?', 3, '[{"text": "Kunde", "correct": true, "because": "Liefert Anforderungen"}, {"text": "Fachinformatiker", "correct": true, "because": "Formuliert technisch"}, {"text": "Projektleiter", "correct": true, "because": "Koordiniert Prozess"}, {"text": "Lieferant", "correct": false, "because": "Später involviert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien machen ein Pflichtenheft hochwertig?', 4, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Klarheit für alle"}, {"text": "Präzision", "correct": true, "because": "Vermeidet Mehrdeutigkeit"}, {"text": "Vollständigkeit", "correct": true, "because": "Deckt alles ab"}, {"text": "Kürze", "correct": false, "because": "Nicht primär entscheidend"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Pflichtenheft beschreibt die Soll-Zustände eines Systems. b) Es wird vom Kunden allein erstellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Soll-Zustände ja, Kunde erstellt Lastenheft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Änderungen im Pflichtenheft sind nach Freigabe möglich. b) Ein Pflichtenheft enthält keine Abnahmekriterien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Änderungen ja, Abnahmekriterien gehören dazu"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Pflichtenheft basiert auf dem Lastenheft. b) Es ist ein unverbindliches Dokument.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lastenheft ja, Verbindlichkeit gegeben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Pflichtenheft wird vom Dienstleister erstellt. b) Es dient nur der internen Kommunikation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dienstleister ja, auch für Kunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Pflichtenheft definiert auch nicht-funktionale Anforderungen. b) Es wird erst nach der Installation erstellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht-funktional ja, vor Installation"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

